package uk.co.traynor.privategallery.core.arcade;
import java.io.*;
import java.util.Arrays;
/** Four clue-density levels; each generated puzzle is independently checked for uniqueness. */
public final class SudokuGame {
 private final int[] givens,solution,board,notes;private final SudokuGame previous;
 public final int level,mistakes,hints;public final long seconds;public final boolean paused,completedOnce;
 private SudokuGame(int[] givens,int[] solution,int[] board,int[] notes,int level,int mistakes,int hints,long seconds,boolean paused,SudokuGame previous){this(givens,solution,board,notes,level,mistakes,hints,seconds,paused,previous,false);}
 private SudokuGame(int[] givens,int[] solution,int[] board,int[] notes,int level,int mistakes,int hints,long seconds,boolean paused,SudokuGame previous,boolean completedOnce){this.givens=givens.clone();this.solution=solution.clone();this.board=board.clone();this.notes=notes.clone();this.level=level;this.mistakes=mistakes;this.hints=hints;this.seconds=seconds;this.paused=paused;this.previous=previous;this.completedOnce=completedOnce||Arrays.equals(board,solution);}
 public static SudokuGame create(int level,long seed){ArcadeCodec.require(level>=0&&level<4);ArcadeCodec.Random r=new ArcadeCodec.Random(seed);int[] digits={1,2,3,4,5,6,7,8,9},rows=order(r),cols=order(r);r.shuffle(digits);int[] solution=new int[81];for(int y=0;y<9;y++)for(int x=0;x<9;x++)solution[y*9+x]=digits[(rows[y]*3+rows[y]/3+cols[x])%9];int[] givens=solution.clone(),indices=new int[81];for(int i=0;i<81;i++)indices[i]=i;r.shuffle(indices);int target=new int[]{42,35,29,25}[level],count=81;for(int at:indices){int old=givens[at];givens[at]=0;if(SudokuSolver.count(givens,2)!=1)givens[at]=old;else count--;if(count<=target)break;}ArcadeCodec.require(SudokuSolver.count(givens,2)==1);return new SudokuGame(givens,solution,givens,new int[81],level,0,0,0,false,null);}
 private static int[] order(ArcadeCodec.Random r){int[] bands={0,1,2},result=new int[9];r.shuffle(bands);for(int i=0;i<3;i++){int[] local={0,1,2};r.shuffle(local);for(int j=0;j<3;j++)result[i*3+j]=bands[i]*3+local[j];}return result;}
 public int cell(int i){return board[i];}public int given(int i){return givens[i];}public int note(int i){return notes[i];}public int[] givens(){return givens.clone();}public int[] solution(){return solution.clone();}public boolean canUndo(){return previous!=null;}public boolean complete(){return Arrays.equals(board,solution);}public boolean wrong(int i){return board[i]!=0&&board[i]!=solution[i];}
 private SudokuGame snapshot(){return new SudokuGame(givens,solution,board,notes,level,mistakes,hints,seconds,paused,null,completedOnce);}
 public SudokuGame enter(int at,int value,boolean pencil){ArcadeCodec.require(at>=0&&at<81&&value>=0&&value<=9);if(paused||complete()||givens[at]!=0)return this;int[] b=board.clone(),n=notes.clone();int errors=mistakes;if(pencil&&value!=0){if(b[at]!=0)return this;n[at]^=1<<value;}else{if(b[at]==value&&n[at]==0)return this;b[at]=value;n[at]=0;if(value!=0&&value!=solution[at])errors=Math.min(1_000_000,errors+1);}return new SudokuGame(givens,solution,b,n,level,errors,hints,seconds,paused,snapshot(),completedOnce);}
 public SudokuGame hint(int at){ArcadeCodec.require(at>=0&&at<81);if(paused||complete()||givens[at]!=0||board[at]==solution[at])return this;SudokuGame s=enter(at,solution[at],false);return new SudokuGame(givens,solution,s.board,s.notes,level,mistakes,Math.min(1_000_000,hints+1),seconds,paused,snapshot(),s.completedOnce);}
 public SudokuGame undo(){return previous==null?this:new SudokuGame(givens,solution,previous.board,previous.notes,level,previous.mistakes,previous.hints,seconds,paused,null,completedOnce);}
 public SudokuGame pause(boolean value){return new SudokuGame(givens,solution,board,notes,level,mistakes,hints,seconds,value&&!complete(),previous,completedOnce);}
 public SudokuGame tick(){return paused||complete()?this:new SudokuGame(givens,solution,board,notes,level,mistakes,hints,Math.min(seconds+1,315360000L),paused,previous,completedOnce);}
 private void frame(DataOutputStream out)throws IOException{ArcadeCodec.ints(out,board);ArcadeCodec.ints(out,notes);out.writeInt(mistakes);out.writeInt(hints);}
 public String encode(){return ArcadeCodec.encode(2,out->{out.writeInt(level);ArcadeCodec.ints(out,givens);ArcadeCodec.ints(out,solution);out.writeLong(seconds);out.writeBoolean(paused);frame(out);out.writeBoolean(previous!=null);if(previous!=null)previous.frame(out);out.writeBoolean(completedOnce);});}
 private static SudokuGame frame(DataInputStream in,int[] g,int[] s,int level,long seconds,boolean paused)throws IOException{int[] b=ArcadeCodec.ints(in,81,81),n=ArcadeCodec.ints(in,81,81);int mistakes=in.readInt(),hints=in.readInt();ArcadeCodec.require(mistakes>=0&&mistakes<=1_000_000&&hints>=0&&hints<=1_000_000);for(int i=0;i<81;i++)ArcadeCodec.require(b[i]>=0&&b[i]<=9&&(g[i]==0||b[i]==g[i])&&n[i]>=0&&(n[i]&~1022)==0&&(b[i]==0||n[i]==0));return new SudokuGame(g,s,b,n,level,mistakes,hints,seconds,paused,null);}
 public static SudokuGame decode(String raw){return ArcadeCodec.decode(raw,2,in->{int level=in.readInt();ArcadeCodec.require(level>=0&&level<4);int[] g=ArcadeCodec.ints(in,81,81),s=ArcadeCodec.ints(in,81,81);ArcadeCodec.require(SudokuSolver.valid(s,true)&&SudokuSolver.valid(g,false));for(int i=0;i<81;i++)ArcadeCodec.require(g[i]==0||g[i]==s[i]);ArcadeCodec.require(SudokuSolver.count(g,2)==1);long seconds=in.readLong();ArcadeCodec.require(seconds>=0&&seconds<=315360000L);boolean paused=ArcadeCodec.bool(in);SudokuGame state=frame(in,g,s,level,seconds,paused),previous=ArcadeCodec.bool(in)?frame(in,g,s,level,seconds,paused):null;boolean credited=ArcadeCodec.bool(in);ArcadeCodec.require(credited||!state.complete());return new SudokuGame(g,s,state.board,state.notes,level,state.mistakes,state.hints,seconds,paused,previous,credited);});}
}
